from pathlib import Path
import os
import pytest

from utils import get_buggy_files

import autopep8

from.utils import test_dir, run_autopep8, run_fix, write_file


def test_buggy_autopep8():
    bugs = get_buggy_files(autopep8)

    for bug in bugs:
        assert len(bug.fixes) == 1


def test_autopep8():
    assert autopep8.fix_code('import sys') == "import sys\n"
    assert autopep8.fix_code('import sys') == "import sys\n"
    assert autopep8.fix_code('import sys') == "import sys\n"
    assert autopep8.fix_code("x = (1, 2, 3)") == "x = (1, 2, 3)\n"
    assert autopep8.fix_code("x = (1, 2, 3)") == "x = (1, 2, 3)\n"
    assert autopep8.fix_code("x = (1, 2, 3)") == "x = (1, 2, 3)\n"
    assert autopep8.fix_code("if a > 10:\n    pass") == "if a > 10:\n    pass\n"
    assert autopep8.fix_code("if a > 10:\n    pass") == "if a > 10:\n    pass\n"
    assert autopep8.fix_code("if a > 10:\n    pass") == "if a > 10:\n    pass\n"
    assert autopep8.fix_code("try:\n    raise ValueError") == "try:\n    raise ValueError\n"
    assert autopep8.fix_code("try:\n    raise ValueError") == "try:\n    raise ValueError\n"
    assert autopep8.fix_
